public int findMaxConsecutive(int[] arr) {
    // Edge case: If the array is empty, return 0
    if (arr.length == 0) {
        return 0;
    }

    // Initialize variables
    // maxCount will store the length of the longest sequence found
    // currentCount will track the length of the sequence we are currently in
    // We start at 1 because a sequence of at least one element is guaranteed for any non-empty array
    int maxCount = 1; 
    int currentCount = 1;

    // Start loop from index 1. index 0 is the start of the first sequence.
    for (int i = 1; i < arr.length; i++) {

        // Check if the current element matches the previous one
        if (arr[i] == arr[i - 1]) {
            // If they match, increase the count of the current sequence
            currentCount++;
        } else {
            // If they don't match, we have finished a sequence.
            // Check if the current sequence was longer than the max seen so far.
            if (currentCount > maxCount) {
                maxCount = currentCount;
            }
            // Start a new sequence starting from this current element
            currentCount = 1;
        }
    }

    // After the loop finishes, there might be a remaining sequence in tail. 
    // It is important to check it one last time.
    if (currentCount > maxCount) {
        maxCount = currentCount;
    }

    return maxCount;
}
